// Runtime lighting for the OpenGL normal map generated by
// Hugo-Dz/spritefusion-sprite-normals. No additional visible logo layers.

/** Move a studio light with the pointer, then undo the card's rotation.
 * Canvas/card Y points down; the OpenGL normal texture's Y points up. */
export function localLight(tx: number, ty: number) {
  const ax = ty * 20 * Math.PI / 180, ay = -tx * 30 * Math.PI / 180;
  const cx = Math.cos(ax), sx = Math.sin(ax), cy = Math.cos(ay), sy = Math.sin(ay);
  const wx = tx * 1.2 - .45, wy = ty * 1.0 - .6, wz = 1.1;
  const y1 = wy * cx + wz * sx, z1 = -wy * sx + wz * cx;
  const x = wx * cy - z1 * sy, y = -y1, z = wx * sy + z1 * cy;
  const length = Math.hypot(x, y, z);
  // View vector in the same tangent space, for per-bead specular response.
  const vx = -cx * sy, vy = -sx, vz = cx * cy;
  const lx = x / length, ly = y / length, lz = z / length;
  const hx = lx + vx, hy = ly + vy, hz = lz + vz;
  const halfLength = Math.hypot(hx, hy, hz) || 1;
  return { lx, ly, lz, hx: hx / halfLength, hy: hy / halfLength, hz: hz / halfLength };
}

export function decodeNormals(data: Uint8ClampedArray) {
  const normals = new Float32Array(data.length / 4 * 3);
  for (let p = 0, n = 0; p < data.length; p += 4, n += 3) {
    const x = data[p] / 127.5 - 1, y = data[p + 1] / 127.5 - 1, z = data[p + 2] / 127.5 - 1;
    const length = Math.hypot(x, y, z) || 1;
    normals[n] = x / length; normals[n + 1] = y / length; normals[n + 2] = z / length;
  }
  return normals;
}

/** A soft diagonal light ribbon, not a replacement for the cursor's spot. */
export function shimmerAt(u: number, v: number, seconds?: number) {
  if (seconds === undefined) return 0;
  const center = (seconds % 5.8) / 5.8 * 2.4 - 1.2;
  const band = Math.max(0, 1 - Math.abs(u + v * .55 - center) / .16);
  return band * band * (3 - 2 * band);
}

/** Staggered glints: each fades in/out, rests, then chooses a new bead. */
export function sparkleAt(seconds: number, slot: number, count: number) {
  const clock = Math.max(0, seconds) + slot * .83;
  const cycle = Math.floor(clock / 2.7);
  const phase = clock % 2.7;
  const hash = Math.sin((cycle + 1) * 127.1 + (slot + 1) * 311.7) * 43758.5453;
  return {
    index: Math.floor((hash - Math.floor(hash)) * count),
    strength: phase < 1.15 ? Math.sin(phase / 1.15 * Math.PI) ** 2 : 0,
  };
}

/** Reuse buffers and touch only artwork pixels, not the transparent background. */
export function shadeNormalPixels(
  source: Uint8ClampedArray, normals: Float32Array, active: Uint32Array,
  result: Uint8ClampedArray, tx: number, ty: number, width: number, seconds?: number,
) {
  const { lx, ly, lz, hx, hy, hz } = localLight(tx, ty);
  const height = source.length / (4 * width);
  // A studio spot aimed by the cursor. Its footprint travels across the
  // artwork in both axes; normals shape the individual bead reflections.
  const lightU = tx * .28, lightV = -ty * .28;
  for (let i = 0; i < active.length; i++) {
    const pixel = active[i], k = pixel * 4, n = pixel * 3;
    const nx = normals[n], ny = normals[n + 1], nz = normals[n + 2];
    const diffuse = Math.max(0, nx * lx + ny * ly + nz * lz);
    const half = Math.max(0, nx * hx + ny * hy + nz * hz);
    const s2 = half * half, s4 = s2 * s2, s8 = s4 * s4, s16 = s8 * s8;
    const specular = s16;
    const u = (pixel % width + .5) / width - .5;
    const v = .5 - (Math.floor(pixel / width) + .5) / height;
    const du = u - lightU, dv = v - lightV;
    const falloff = .045 / (.045 + du * du + dv * dv);
    const spot = falloff * falloff;
    // Low colored fill keeps unlit beads readable, while the cursor's spot
    // supplies most of the illumination instead of a uniformly bright base.
    const wave = shimmerAt(u, v, seconds);
    const energy = .32 + diffuse * .12 + spot * (1.15 + diffuse * .75 + specular * 1.20)
      + wave * (.75 + specular * .45);
    const pearl = spot * specular * .36 + wave * .16;
    result[k] = source[k] + (255 - source[k]) * pearl;
    result[k + 1] = source[k + 1] + (255 - source[k + 1]) * pearl;
    result[k + 2] = source[k + 2] + (255 - source[k + 2]) * pearl;
    result[k + 3] = Math.min(255, source[k + 3] * energy);
  }
}

export function createNormalLighting(source: ImageData, normalMap: ImageData) {
  if (source.width !== normalMap.width || source.height !== normalMap.height)
    throw new Error("Sprite Fusion normal map must match the bead artwork dimensions.");
  const normals = decodeNormals(normalMap.data);
  const pixels: number[] = [];
  for (let k = 3; k < source.data.length; k += 4) if (source.data[k]) pixels.push((k - 3) / 4);
  const active = Uint32Array.from(pixels);
  const bright = active.filter(pixel => source.data[pixel * 4 + 3] > 165);
  const canvas = document.createElement("canvas");
  canvas.width = source.width; canvas.height = source.height;
  const ctx = canvas.getContext("2d")!;
  const output = new ImageData(source.width, source.height);
  let previous = "";
  return {
    render(tx: number, ty: number, seconds?: number) {
      const key = `${tx.toFixed(4)}:${ty.toFixed(4)}:${seconds ?? "still"}`;
      if (key !== previous) {
        shadeNormalPixels(source.data, normals, active, output.data, tx, ty, source.width, seconds);
        ctx.putImageData(output, 0, 0);
        if (seconds !== undefined && bright.length) {
          // Draw directly into this material, so glints follow the same mesh
          // and never become a separate floating/doubled artwork layer.
          ctx.save();
          ctx.globalCompositeOperation = "lighter";
          for (let slot = 0; slot < 4; slot++) {
            const { index, strength } = sparkleAt(seconds, slot, bright.length);
            if (strength < .015) continue;
            const pixel = bright[index], k = pixel * 4;
            const x = pixel % source.width + .5, y = Math.floor(pixel / source.width) + .5;
            const size = source.width / 768;
            const radius = (17 + slot * 2) * size;
            const glow = ctx.createRadialGradient(x, y, 0, x, y, radius);
            const color = `${source.data[k]},${source.data[k + 1]},${source.data[k + 2]}`;
            glow.addColorStop(0, `rgba(255,255,245,${strength})`);
            glow.addColorStop(.16, `rgba(255,250,230,${strength * .9})`);
            glow.addColorStop(.42, `rgba(${color},${strength * .35})`);
            glow.addColorStop(1, `rgba(${color},0)`);
            ctx.fillStyle = glow;
            ctx.fillRect(x - radius, y - radius, radius * 2, radius * 2);
            const ray = (9 + slot) * size * (.6 + strength * .4);
            ctx.fillStyle = `rgba(255,255,245,${strength * .95})`;
            ctx.beginPath();
            ctx.moveTo(x, y - ray);
            ctx.lineTo(x + size, y - size);
            ctx.lineTo(x + ray * .7, y);
            ctx.lineTo(x + size, y + size);
            ctx.lineTo(x, y + ray);
            ctx.lineTo(x - size, y + size);
            ctx.lineTo(x - ray * .7, y);
            ctx.lineTo(x - size, y - size);
            ctx.closePath(); ctx.fill();
          }
          ctx.restore();
        }
        previous = key;
      }
      return canvas;
    },
    dispose() { canvas.width = canvas.height = 0; },
  };
}
